  bindCustomTheme() {
    const { themeCustom, customPalettePanel, closePalette, pickerPrimary, pickerSecondary, pickerTertiary } = this.els;
    if (!themeCustom || !customPalettePanel) return;

    try {
      const saved = JSON.parse(localStorage.getItem("portfolio-custom-palette"));
      if (saved) {
        if (saved.primary && pickerPrimary) { pickerPrimary.value = saved.primary; document.documentElement.style.setProperty("--green", saved.primary); }
        if (saved.secondary && pickerSecondary) { pickerSecondary.value = saved.secondary; document.documentElement.style.setProperty("--cyan", saved.secondary); }
        if (saved.tertiary && pickerTertiary) { pickerTertiary.value = saved.tertiary; document.documentElement.style.setProperty("--panel", saved.tertiary); }
      }
    } catch {}

    themeCustom.addEventListener("click", () => {
      customPalettePanel.classList.toggle("is-open");
      customPalettePanel.setAttribute("aria-hidden", !customPalettePanel.classList.contains("is-open"));
    });

    closePalette?.addEventListener("click", () => {
      customPalettePanel.classList.remove("is-open");
      customPalettePanel.setAttribute("aria-hidden", "true");
    });

    const updateColors = () => {
      const primary = pickerPrimary?.value || "#20ef4f";
      const secondary = pickerSecondary?.value || "#00f0ff";
      const tertiary = pickerTertiary?.value || "#090b0a";
      document.documentElement.style.setProperty("--green", primary);
      document.documentElement.style.setProperty("--cyan", secondary);
      document.documentElement.style.setProperty("--panel", tertiary);
      document.body.dataset.theme = "custom";
      try {
        localStorage.setItem("portfolio-custom-palette", JSON.stringify({ primary, secondary, tertiary }));
      } catch {}
    };

    pickerPrimary?.addEventListener("input", updateColors);
    pickerSecondary?.addEventListener("input", updateColors);
    pickerTertiary?.addEventListener("input", updateColors);
  },
