﻿/* Cyber Minesweeper Arcade App Icon & Modal Styles */
.minesweeper-app-icon-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  background: transparent;
  border: none;
  padding: 12px;
  cursor: pointer;
  transition: all 0.2s ease;
  text-align: center;
  pointer-events: auto;
  width: 100%;
}

.minesweeper-app-icon-card:hover {
  border: none;
  transform: translateY(-3px);
  box-shadow: none;
}

.minesweeper-app-icon {
  width: 72px;
  height: 72px;
  background: var(--ink);
  border: 1px solid var(--green);
  display: grid;
  place-items: center;
  box-shadow: inset 0 0 10px color-mix(in srgb, var(--green) 15%, transparent);
  position: relative;
  pointer-events: none;
}

.minesweeper-icon-canvas {
  width: 56px;
  height: 56px;
  display: block;
  pointer-events: none;
}

.minesweeper-icon-label {
  font-family: var(--display);
  font-size: 16px;
  color: var(--paper);
  margin: 0;
  pointer-events: none;
}

/* Modal Overlay */
.minesweeper-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(9, 11, 10, 0.85);
  backdrop-filter: blur(4px);
  z-index: 1000;
  display: grid;
  place-items: center;
  padding: 12px;
  opacity: 0;

.tetris-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(9, 11, 10, 0.85);
  backdrop-filter: blur(8px);
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
}

.tetris-modal-overlay.is-active {
  opacity: 1;
  pointer-events: auto;
}

.tetris-modal-container {
  background: var(--surface);
  border: 1px solid var(--cyan);
  box-shadow: 0 0 30px rgba(145, 243, 168, 0.2);
  width: 100%;
  max-width: 440px;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
}

.tetris-header {
  width: 100%;
